import io.rsocket.Payload;
import io.rsocket.AbstractRSocket;
import io.rsocket.util.DefaultPayload;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

public class DataStreamRSocketServer extends AbstractRSocket {

    @Override
    public Flux<Payload> requestStream(Payload payload) {
        // Simulating a reactive stream pushing items downstream with backpressure support
        return Flux.interval(java.time.Duration.ofMillis(100))
                index()
                .map(tuple -> DefaultPayload.create("Stream Item: " + tuple.getT1()));
    }

    @Override
    public Mono<Payload> requestResponse(Payload payload) {
        String requestString = payload.getDataUtf8();
        return Mono.just(DefaultPayload.create("Echo: " + requestString));
    }
}
